     ResultSet rs = st.executeQuery("SELECT id, name FROM users")) {
    rs.last();                       // jump to the last row
    int rowCount = rs.getRow();      // how many rows total
    rs.beforeFirst();                // back to the start
    while (rs.next()) { /* forward */ }
    rs.absolute(3);                  // jump to row 3
    rs.previous();                   // step backward to row 2
